        controller->testConnection(configuration,[guard,check,result,controller](const QString& error){if(!guard)return;check->setEnabled(true);const auto state=controller->state();result->setText(error.isEmpty()?QString("Connection OK · %1 Hz · %2").arg(state.value("frequencyHz").toString(),state.value("mode").toString()):error);});
